/* Where everything sits when the journey opens, shared by the first picture (paint.js) and the 3D scene (sky.js) so the
   hand over between them is invisible. Positions are fractions of the screen: [x, y] from the top left, the depth z,
   and the height as a fraction of the screen at that depth. */
window.SKY_L = (() => {
  const L = {
    SUN: { wide: [0.700, 0.556], tall: [0.752, 0.499] },
    ASPECT: { wide: 2880 / 1376, tall: 1440 / 2580 },
    // the light: islands and clouds are lit from behind by the low sun, so the side facing us falls into warm shadow
    SHADE: { isle: [176, 108, 104, .26], cloud: [246, 186, 150, .26] },
    wide: {
      isles: { hatch: [.84, .28, 6200, .2], shrine: [.14, .44, 4200, .09], meadow: [.43, .61, 1500, .55], lantern: [.72, .6, 3600, .23], bamboo: [1.9, .68, 900, .45] },   // one hero: the meadow and its beacon, centre stage
      //        x    y    z     h    opacity kind   flip squash
      clouds: [],   // the near clouds are painted into the sky itself: no cut edges anywhere
    },
    tall: {
      isles: { hatch: [.7, .29, 6200, .12], shrine: [.2, .4, 4200, .06], meadow: [.46, .598, 1500, .27], lantern: [.66, .62, 3600, .112], bamboo: [1.9, .7, 900, .3] },
      clouds: [],
    },
  };
  L.shape = () => (innerHeight > innerWidth ? 'tall' : 'wide');
  L.haze = (z, name) => Math.min(.62, Math.max(0, (z - 800) / 7000)) * (name === 'hatch' ? .45 : 1);   // the destination stays clear
  // the sky colour behind a point on screen, read from the painting itself (sRGB 0 to 255)
  const probe = {};
  L.skyAt = (img, shape, sx, sy) => {
    if (!img || !img.naturalWidth) return [238, 180, 146];
    let p = probe[shape];
    if (!p) { const c = document.createElement('canvas'); c.width = 96; c.height = Math.round(96 / L.ASPECT[shape]); const x = c.getContext('2d', { willReadFrequently: true }); x.drawImage(img, 0, 0, c.width, c.height); p = probe[shape] = { x, w: c.width, h: c.height }; }
    // the screen point mapped through the painting's cover fit
    const W = innerWidth, H = innerHeight, ia = L.ASPECT[shape]; let bw = W, bh = W / ia; if (bh < H) { bh = H; bw = H * ia; }
    const u = Math.max(0, Math.min(1, (sx * W - (W - bw) / 2) / bw)), v = Math.max(0, Math.min(1, (sy * H - (H - bh) / 2) / bh));
    const d = p.x.getImageData(Math.min(p.w - 1, Math.round(u * (p.w - 1))), Math.min(p.h - 1, Math.round(v * (p.h - 1))), 1, 1).data;
    return [d[0], d[1], d[2]];
  };
  // the sky colour at a point on the painting itself (u, v from the top left, 0 to 1)
  L.skyUV = (img, shape, u, v) => {
    if (!img || !img.naturalWidth) return [238, 180, 146];
    if (!probe[shape]) L.skyAt(img, shape, .5, .5);
    const p = probe[shape], d = p.x.getImageData(Math.max(0, Math.min(p.w - 1, Math.round(u * (p.w - 1)))), Math.max(0, Math.min(p.h - 1, Math.round(v * (p.h - 1)))), 1, 1).data;
    return [d[0], d[1], d[2]];
  };
  return L;
})();

